   \"@codemirror/legacy-modes\": \"^6.0.0\",\n    \"@codemirror/search\": \"^6.0.0\",\n    \"@codemirror/state\": \"^6.0.0\",\n    \"@codemirror/view\": \"^6.0.0\",\n    \"@lezer/highlight\": \"^1.0.0\",\n    \"@types/node\": \"^22.0.0\",\n    \"@types/react\": \"^18.2.0\",\n    \"@types/react-dom\": \"^18.2.0\",\n    \"tsdown\": \"^0.22.14\",\n    \"typescript\": \"^6.0.3\",\n    \"cordis\": \"^4.0.0-rc.7\"\n  }\n}\n"
