function DownloadIndicator({ count }: { count: number }): ReactNode {
  const [rotation, setRotation] = useState(0)
  useEffect(() => {
    if (count === 0) return
    const timer = window.setInterval(() => {
      setRotation((value) => (value + 12) % 360)
    }, 50)
